package Operatorsinjava;

public class Operator7 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub

		int i =5;

		int j=23;

		// Conditional operators
		// && ,||

		System.out.println(i==j && i<j);
		
		System.out.println(i==j || i<j);

		

	}

}
